// 运行器自动生成的文件，每次运行都会覆盖，不要修改。
// Generated by the runner and overwritten on every run; do not edit.
// Helpers every dojo's tests use: fail()/say() report a failure code the web UI has a hint for,
// Trace records a timeline the UI draws, within()/until() keep a hung test from taking 20 s.
import { writeFileSync } from "node:fs";
import { join } from "node:path";

/** A message in both languages: say("期望 3 个，实际 2 个。", "Expected 3, got 2."). Build both with the same values. */
export function say(zh: string, en: string): { zh: string; en: string } {
	return { zh, en };
}

/**
 * Stop the test with a failure the UI understands. `code` picks the targeted hint (byCode in
 * web/js/dojos/<id>.js); `msg` is shown to the learner as is, in their language, so say what was
 * expected, what happened, and the likely cause.
 */
export function fail(code: string, msg: { zh: string; en: string }, extra: Record<string, unknown> = {}): never {
	throw new Error("DOJO_FAIL " + JSON.stringify({ code, msg: msg.zh, msg_en: msg.en, ...extra }));
}

/** Events for the UI's timeline: lanes with begin→end bars and marks. Saved under the test's name. */
export class Trace {
	readonly #t0 = performance.now();
	readonly events: { t: number; lane: string; k: "begin" | "end" | "mark"; id: string; label: string; label_en?: string; bad?: boolean }[] = [];
	/** A language-neutral label, such as a task name. */
	add(lane: string, k: "begin" | "end" | "mark", id: string, label: string, bad = false): void {
		this.events.push({ t: (performance.now() - this.#t0) / 1000, lane, k, id, label, bad });
	}
	/** A label in both languages: addL(lane, "mark", "", "进程关掉了", "process closed", true). */
	addL(lane: string, k: "begin" | "end" | "mark", id: string, zh: string, en: string, bad = false): void {
		this.events.push({ t: (performance.now() - this.#t0) / 1000, lane, k, id, label: zh, label_en: en, bad });
	}
	save(name: string): void {
		const dir = process.env.DOJO_TRACE_DIR;
		if (!dir) return;
		const t_end = (performance.now() - this.#t0) / 1000;
		writeFileSync(join(dir, name + ".json"), JSON.stringify({ t_end, events: this.events }));
	}
}

/** Wait until `test()` is true, polling every 5 ms; false after `ms`. */
export async function until(test: () => boolean, ms: number): Promise<boolean> {
	const end = Date.now() + ms;
	while (!test()) {
		if (Date.now() > end) return false;
		await new Promise((r) => setTimeout(r, 5));
	}
	return true;
}

/** Reject after `ms`, so a hung task fails with a message instead of a 20 s timeout. */
export function within<T>(ms: number, p: Promise<T>, onTimeout: () => never): Promise<T> {
	let timer: ReturnType<typeof setTimeout>;
	return Promise.race([p, new Promise<T>((_, reject) => { timer = setTimeout(() => { try { onTimeout(); } catch (e) { reject(e); } }, ms); })]).finally(() => clearTimeout(timer));
}
